<?php require dirname(__DIR__).'/core/bootstrap.php';$u=auth();$admin=false;require ROOT.'/includes/panel.php';?><h1>Minhas licenças.</h1><p class="muted">As chaves são disponibilizadas pelo administrador por canal autenticado. A chave completa não é armazenada em texto no banco.</p><div class="table-wrap"><table><tr><th>Produto</th><th>Domínio</th><th>Vencimento</th><th>Status</th><th>Renovação</th></tr><?php foreach(rows('SELECT l.*,p.name FROM licenses l JOIN products p ON p.id=l.product_id WHERE l.user_id=? ORDER BY l.id DESC',[$u['id']]) as $l):?><tr><td><?=e($l['name'])?></td><td><?=e($l['domain'])?></td><td><?=e(datebr($l['expires_at']))?></td><td><?=e($l['status']==='active'&&(!$l['expires_at']||$l['expires_at']>=date('Y-m-d'))?'Ativa':'Suspensa / vencida')?></td><td><a href="<?=e(url('cliente/suporte.php?assunto='.rawurlencode('Renovação licença #'.$l['id'])))?>">Solicitar ↗</a></td></tr><?php endforeach;?></table></div><?php require ROOT.'/includes/endpanel.php';?>
